const quotes = [
  { text: '천 리 길도 한 걸음부터.', author: '노자' },
  { text: '오늘 할 수 있는 일을 내일로 미루지 마라.', author: '벤저민 프랭클린' },
  { text: '실패는 성공의 어머니다.', author: '속담' },
  { text: '행복은 습관이다. 그것을 몸에 지니라.', author: '허버드' },
  { text: '가장 큰 영광은 한 번도 실패하지 않음이 아니라 실패할 때마다 다시 일어서는 데 있다.', author: '공자' },
  { text: '배움에는 끝이 없다.', author: '속담' },
  { text: '작은 기회로부터 종종 위대한 업적이 시작된다.', author: '데모스테네스' },
  { text: '꿈을 기록하는 것이 나의 목표였던 적은 없다. 꿈을 실현하는 것이 나의 목표다.', author: '만 레이' },
  { text: '지금 이 순간을 즐겨라.', author: '호라티우스' },
  { text: '변화를 원한다면 스스로 그 변화가 되어라.', author: '마하트마 간디' }
];

const pick = quotes[Math.floor(Math.random() * quotes.length)];
const line = `"${pick.text}" — ${pick.author}`;

// 콘솔 출력 (n8n 서버 로그 / 수동 실행 시 브라우저 개발자도구 콘솔)
console.log(`[좋은 글귀] ${line}`);

return [{
  json: {
    quote: pick.text,
    author: pick.author,
    line,
    generatedAt: new Date().toISOString()
  }
}];

